package com.dating.backend.matching;
import com.dating.backend.entity.*;import jakarta.persistence.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class AccountService {
 private final EntityManager em;private final PasswordEncoder passwords;
 public record Settings(boolean resting,String provider,String reviewStatus,String reviewNote,AccountPreferences notifications,List<TermsConsent> consents){}
 public record Preferences(boolean likes,boolean matches,boolean messages,boolean recommendations,boolean service,boolean quietHours,int quietStart,int quietEnd){}
 public record PasswordChange(String currentPassword,String newPassword){}
 public record Withdrawal(String password,String confirmation){}
 private User user(String email){return em.createQuery("select u from User u where u.email=:e and u.status<>'DELETED'",User.class).setParameter("e",email).getResultStream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));}
 @Transactional public Settings get(String email){var u=user(email);em.lock(u,LockModeType.PESSIMISTIC_WRITE);var p=em.find(AccountPreferences.class,u.getId());if(p==null){p=new AccountPreferences();p.setUserId(u.getId());em.persist(p);}return new Settings(u.isResting(),u.getProvider(),u.getProfileReviewStatus(),u.getProfileReviewNote(),p,em.createQuery("select t from TermsConsent t where t.userId=:u order by t.id desc",TermsConsent.class).setParameter("u",u.getId()).getResultList());}
 @Transactional public Settings rest(String email,boolean rest){var u=user(email);u.setResting(rest);return get(email);}
 @Transactional public Settings preferences(String email,Preferences r){if(r==null||r.quietStart()<0||r.quietStart()>23||r.quietEnd()<0||r.quietEnd()>23||r.quietHours()&&r.quietStart()==r.quietEnd())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"방해금지 시간을 확인해 주세요.");var p=get(email).notifications();p.setLikes(r.likes());p.setMatches(r.matches());p.setMessages(r.messages());p.setRecommendations(r.recommendations());p.setService(r.service());p.setQuietHours(r.quietHours());p.setQuietStart(r.quietStart());p.setQuietEnd(r.quietEnd());return get(email);}
 @Transactional public void password(String email,PasswordChange r){var u=user(email);em.lock(u,LockModeType.PESSIMISTIC_WRITE);verifyPassword(u,r.currentPassword());if(r.newPassword()==null||r.newPassword().length()<8||r.newPassword().length()>72)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"새 비밀번호는 8~72자로 입력해 주세요.");u.setPassword(passwords.encode(r.newPassword()));revoke(u);}
 @Transactional public void logoutAll(String email){var u=user(email);em.lock(u,LockModeType.PESSIMISTIC_WRITE);revoke(u);}
 @Transactional public void withdraw(String email,Withdrawal r){var u=user(email);em.lock(u,LockModeType.PESSIMISTIC_WRITE);if(r==null||!"회원탈퇴".equals(r.confirmation()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"회원탈퇴를 정확히 입력해 주세요.");if(u.getPassword()!=null&&!u.getPassword().isBlank())verifyPassword(u,r.password());u.setStatus("DELETED");u.setResting(true);u.setDeletedAt(LocalDateTime.now());u.setResetPasswordToken(null);u.setResetPasswordTokenExpiresAt(null);revoke(u);}
 private void verifyPassword(User u,String value){if(u.getPassword()==null||value==null||!passwords.matches(value,u.getPassword()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"현재 비밀번호를 확인해 주세요.");}
 private void revoke(User u){u.setSessionVersion(u.getSessionVersion()+1);em.createQuery("update RefreshToken t set t.revoked=true,t.revokedAt=:now where t.userId=:u").setParameter("now",LocalDateTime.now()).setParameter("u",u.getId()).executeUpdate();em.createQuery("delete from PushDevice d where d.userId=:u").setParameter("u",u.getId()).executeUpdate();}
 public static boolean allowed(AccountPreferences p,String key){if(p==null)return true;if(key.startsWith("LIKE:"))return p.isLikes();if(key.startsWith("MATCH:"))return p.isMatches();if(key.startsWith("CHAT:"))return p.isMessages();if(key.startsWith("TODAY:"))return p.isRecommendations();return p.isService();}
 public static boolean quiet(AccountPreferences p,int hour){return p!=null&&p.isQuietHours()&&(p.getQuietStart()<p.getQuietEnd()?hour>=p.getQuietStart()&&hour<p.getQuietEnd():hour>=p.getQuietStart()||hour<p.getQuietEnd());}
}
